const availablePlanTemplates=defaults.filter(p=>p.id!=='light');
let addedTemplates=false;
for(const template of availablePlanTemplates){
  if(!plans.some(p=>p.id===template.id||p.name===template.name)){
    plans.push(structuredClone(template));addedTemplates=true;
  }
}
if(addedTemplates)localStorage.setItem('hwt-plans',JSON.stringify(plans));

