function exerciseGuide(name,group){
 if(EXERCISE_GUIDES[name])return EXERCISE_GUIDES[name];
 const n=String(name||'').toLowerCase();
 if(n.includes('przysiad')||n.includes('wykrok'))return ['Ustaw stopy stabilnie i napnij tułów.','Wykonuj ruch powoli, prowadząc kolano zgodnie z kierunkiem stopy.'];
 if(n.includes('wiosłow')||n.includes('ściągan')||n.includes('pull'))return ['Ustaw łopatki stabilnie i nie unoś barków do uszu.','Przyciągaj opór w kontrolowany sposób, bez bujania tułowiem.'];
 if(n.includes('wyciskan')||n.includes('press'))return ['Ustaw stabilną pozycję i napnij brzuch.','Wyciskaj ciężar płynnie, bez szarpania i wyginania pleców.'];
 if(n.includes('uginan')||n.includes('curl'))return ['Trzymaj łokcie możliwie nieruchomo przy ciele.','Unoś ciężar bez rozkołysania i opuszczaj powoli.'];
 if(n.includes('rozciąg')||group==='Rozciąganie')return ['Wejdź powoli w pozycję lekkiego rozciągania.','Oddychaj spokojnie; nie sprężynuj i nie wymuszaj zakresu.'];
 if(group==='Mobilność')return ['Rozpocznij od małego, komfortowego zakresu ruchu.','Wykonuj powtórzenia płynnie, bez bólu i gwałtownych ruchów.'];
 if(group==='Core')return ['Napnij delikatnie brzuch i zachowaj neutralną pozycję kręgosłupa.','Poruszaj się spokojnie, utrzymując kontrolę i regularny oddech.'];
 if(group==='Kondycja')return ['Zacznij w umiarkowanym tempie i zadbaj o swobodny oddech.','Utrzymuj technikę; zmniejsz tempo, kiedy tracisz kontrolę ruchu.'];
 return ['Przyjmij stabilną pozycję i dobierz komfortowy zakres ruchu.','Wykonuj powtórzenia bez pośpiechu i bez bólu; oddychaj regularnie.'];
}

